--
-- Table structure for table `cozinha_pedido`
--

DROP TABLE IF EXISTS `cozinha_pedido`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cozinha_pedido` (
  `id` int NOT NULL AUTO_INCREMENT,
  `loja_id` int NOT NULL,
  `venda_id` int DEFAULT NULL,
  `mesa_id` int DEFAULT NULL,
  `tipo_venda` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AGUARDANDO',
  `prioridade` int NOT NULL DEFAULT '0',
  `observacao` text COLLATE utf8mb4_unicode_ci,
  `criado_em` datetime NOT NULL,
  `iniciado_em` datetime DEFAULT NULL,
  `pronto_em` datetime DEFAULT NULL,
  `entregue_em` datetime DEFAULT NULL,
  `cancelado_em` datetime DEFAULT NULL,
  `criado_por_usuario_id` int DEFAULT NULL,
  `atualizado_por_usuario_id` int DEFAULT NULL,
  `caixa_turno_id` int DEFAULT NULL,
  `numero_pedido` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_cozinha_pedido_atualizado_por_usuario_id` (`atualizado_por_usuario_id`),
  KEY `ix_cozinha_pedido_criado_em` (`criado_em`),
  KEY `ix_cozinha_pedido_criado_por_usuario_id` (`criado_por_usuario_id`),
  KEY `ix_cozinha_pedido_loja_id` (`loja_id`),
  KEY `ix_cozinha_pedido_mesa_id` (`mesa_id`),
  KEY `ix_cozinha_pedido_status` (`status`),
  KEY `ix_cozinha_pedido_venda_id` (`venda_id`),
  KEY `ix_cozinha_pedido_caixa_turno_id` (`caixa_turno_id`),
  CONSTRAINT `cozinha_pedido_ibfk_1` FOREIGN KEY (`atualizado_por_usuario_id`) REFERENCES `usuario` (`id`),
  CONSTRAINT `cozinha_pedido_ibfk_2` FOREIGN KEY (`criado_por_usuario_id`) REFERENCES `usuario` (`id`),
  CONSTRAINT `cozinha_pedido_ibfk_3` FOREIGN KEY (`loja_id`) REFERENCES `loja` (`id`),
  CONSTRAINT `cozinha_pedido_ibfk_4` FOREIGN KEY (`mesa_id`) REFERENCES `mesa` (`id`),
  CONSTRAINT `cozinha_pedido_ibfk_5` FOREIGN KEY (`venda_id`) REFERENCES `venda` (`id`),
  CONSTRAINT `cozinha_pedido_ibfk_6` FOREIGN KEY (`caixa_turno_id`) REFERENCES `caixa_turno` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1559 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

