  `detalhes_json` text COLLATE utf8mb4_unicode_ci,
  `ordem` int NOT NULL DEFAULT '0',
  `impresso_em` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_cozinha_pedido_item_combo_id` (`combo_id`),
  KEY `ix_cozinha_pedido_item_pedido_id` (`pedido_id`),
  KEY `ix_cozinha_pedido_item_produto_id` (`produto_id`),
  CONSTRAINT `cozinha_pedido_item_ibfk_1` FOREIGN KEY (`combo_id`) REFERENCES `cardapio_combo` (`id`),
  CONSTRAINT `cozinha_pedido_item_ibfk_2` FOREIGN KEY (`pedido_id`) REFERENCES `cozinha_pedido` (`id`),
  CONSTRAINT `cozinha_pedido_item_ibfk_3` FOREIGN KEY (`produto_id`) REFERENCES `produto` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2675 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
