DROP TABLE IF EXISTS `delivery_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `delivery_info` (
  `id` int NOT NULL AUTO_INCREMENT,
  `venda_id` int NOT NULL,
  `cliente_nome` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cliente_telefone` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `endereco_rua` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `endereco_numero` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `bairro` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `complemento` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `referencia` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `taxa_entrega` decimal(10,2) NOT NULL,
  `observacoes` text COLLATE utf8mb4_unicode_ci,
  `delivery_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `data_aceito` datetime DEFAULT NULL,
  `data_em_preparo` datetime DEFAULT NULL,
  `data_saiu_entrega` datetime DEFAULT NULL,
  `data_entregue` datetime DEFAULT NULL,
  `data_cancelado` datetime DEFAULT NULL,
  `origem` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `venda_id` (`venda_id`),
  KEY `ix_delivery_info_origem` (`origem`),
  CONSTRAINT `delivery_info_ibfk_1` FOREIGN KEY (`venda_id`) REFERENCES `venda` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=173 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
