-- Table structure for table `integracao_convite`
--

DROP TABLE IF EXISTS `integracao_convite`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `integracao_convite` (
  `id` int NOT NULL AUTO_INCREMENT,
  `loja_id` int NOT NULL,
  `provedor` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `token` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expires_at` datetime NOT NULL,
  `used_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `created_by_user_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_integracao_convite_token` (`token`),
  KEY `created_by_user_id` (`created_by_user_id`),
  KEY `ix_convite_loja_provedor_ativo` (`loja_id`,`provedor`,`used_at`,`expires_at`),
  KEY `ix_integracao_convite_expires_at` (`expires_at`),
  KEY `ix_integracao_convite_loja_id` (`loja_id`),
  KEY `ix_integracao_convite_provedor` (`provedor`),
  KEY `ix_integracao_convite_used_at` (`used_at`),
  CONSTRAINT `integracao_convite_ibfk_1` FOREIGN KEY (`created_by_user_id`) REFERENCES `usuario` (`id`),
  CONSTRAINT `integracao_convite_ibfk_2` FOREIGN KEY (`loja_id`) REFERENCES `loja` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

