  `cep` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `segmento` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `vendedor_id` int DEFAULT NULL,
  `gerenciaEstoque` tinyint(1) DEFAULT NULL,
  `usa_cozinha` tinyint(1) NOT NULL DEFAULT '0',
  `proximo_numero_pedido` int NOT NULL,
  `usa_link_whatsapp` tinyint(1) NOT NULL DEFAULT '0',
  `distancia_max_km` decimal(10,2) DEFAULT NULL,
  `whatsapp_token` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `whatsapp_link` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `logo_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fluxo_pedidos` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'auto',
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_loja_whatsapp_token` (`whatsapp_token`),
  KEY `ix_loja_vendedor_id` (`vendedor_id`),
  KEY `ix_loja_fluxo_pedidos` (`fluxo_pedidos`),
  CONSTRAINT `loja_ibfk_1` FOREIGN KEY (`vendedor_id`) REFERENCES `vendedor` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
